import { Component, ElementRef, inject, input, signal } from '@angular/core';
import { RouterLink } from '@angular/router';
import { TranslateModule } from '@ngx-translate/core';

/** 1 liên kết chéo tới doc page liên quan (atom ↔ ô ghép). */
export interface SgRelated { label: string; route: string; }

/** Khung trang doc 1 component: header + sub-nav + 4 mục
 *  (Overview / Usage / Best practices / Examples) qua content projection.
 *  Chrome khung (tab, tiêu đề mục) i18n qua sg.doc.* — tự đổi VI/EN. */
@Component({
  selector: 'sg-doc',
  imports: [TranslateModule, RouterLink],
  template: `
    <div class="doc-head">
      @if (category()) { <span class="doc-cat">{{ category() }}</span> }
      <h1 class="doc-title">{{ title() }}</h1>
      <p class="doc-desc">{{ desc() }}</p>
      @if (related().length) {
        <div class="doc-related">
          <span class="doc-related-l">{{ 'sg.doc.related' | translate }}</span>
          @for (r of related(); track r.route) {
            <a class="doc-related-link" [routerLink]="'/styleguide/' + r.route">{{ r.label }}</a>
          }
        </div>
      }
    </div>

    <nav class="doc-subnav">
      <button type="button" [class.on]="active() === 'overview'" (click)="go('overview')">{{ 'sg.doc.tab.overview' | translate }}</button>
      <button type="button" [class.on]="active() === 'usage'" (click)="go('usage')">{{ 'sg.doc.tab.usage' | translate }}</button>
      <button type="button" [class.on]="active() === 'best'" (click)="go('best')">{{ 'sg.doc.tab.best' | translate }}</button>
      <button type="button" [class.on]="active() === 'examples'" (click)="go('examples')">{{ 'sg.doc.tab.examples' | translate }}</button>
    </nav>

    <section id="doc-overview" class="doc-sec">
      <h2 class="doc-h2">{{ 'sg.doc.sec.overview' | translate }}</h2>
      <ng-content select="[sgOverview]" />
    </section>
    <section id="doc-usage" class="doc-sec">
      <h2 class="doc-h2">{{ 'sg.doc.sec.usage' | translate }}</h2>
      <ng-content select="[sgUsage]" />
    </section>
    <section id="doc-best" class="doc-sec">
      <h2 class="doc-h2">{{ 'sg.doc.sec.best' | translate }}</h2>
      <ng-content select="[sgBest]" />
    </section>
    <section id="doc-examples" class="doc-sec">
      <h2 class="doc-h2">{{ 'sg.doc.sec.examples' | translate }}</h2>
      <ng-content select="[sgExamples]" />
    </section>
  `,
  styles: [`
    /* Full chiều ngang vùng content (từ side nav sang phải). */
    :host { display: block; width: 100%; }
    .doc-head { margin-bottom: 20px; }
    .doc-cat { font-size: var(--fs-12); font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; color: var(--primary-base); }
    .doc-title { font-size: var(--fs-30); font-weight: 600; color: var(--text-strong); margin: 6px 0 8px; }
    .doc-desc { font-size: var(--fs-15); color: var(--text-sub); line-height: 1.6; margin: 0; max-width: 720px; }
    .doc-related { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-top: 14px; }
    .doc-related-l { font-size: var(--fs-12); font-weight: 600; color: var(--text-soft); text-transform: uppercase; letter-spacing: 0.04em; }
    .doc-related-link {
      font-size: var(--fs-13); font-weight: 500; color: var(--primary-base); text-decoration: none;
      padding: 3px 10px; border-radius: var(--radius-full);
      background: var(--primary-bg-subtle); transition: background var(--duration-fast) var(--ease-out);
    }
    .doc-related-link:hover { background: var(--primary-bg-soft); }
    .doc-subnav {
      position: sticky; top: -32px; z-index: 2;
      display: flex; gap: 4px; padding: 12px 0; margin-bottom: 8px;
      background: var(--bg-app); border-bottom: 1px solid var(--border-sub);
    }
    .doc-subnav button {
      border: 0; background: transparent; cursor: pointer;
      padding: 6px 12px; border-radius: var(--radius-md);
      font-family: var(--font-sans); font-size: var(--fs-13); font-weight: 500; color: var(--text-sub);
    }
    .doc-subnav button:hover { color: var(--text-strong); background: var(--bg-surface-subtle); }
    .doc-subnav button.on { color: var(--primary-base); background: var(--primary-bg-subtle); }
    .dark .doc-subnav button.on { color: var(--text-strong); }
    .doc-sec { padding: 24px 0; border-bottom: 1px solid var(--border-soft); scroll-margin-top: 60px; }
    .doc-h2 { font-size: var(--fs-13); font-weight: 600; text-transform: uppercase; letter-spacing: 0.04em; color: var(--text-soft); margin: 0 0 16px; }
  `],
})
export class SgDoc {
  readonly title = input('');
  readonly desc = input('');
  readonly category = input('');
  /** Liên kết chéo tới doc page liên quan (atom ↔ ô ghép). */
  readonly related = input<SgRelated[]>([]);
  protected readonly active = signal('overview');
  private readonly el = inject(ElementRef);

  protected go(id: string): void {
    this.active.set(id);
    this.el.nativeElement.querySelector(`#doc-${id}`)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }
}
