/** sg-use — hướng dẫn dùng cho BA/Designer (không phải code). */
@Component({
  selector: 'sg-use',
  imports: [TranslateModule],
  template: `
    <div class="u-row"><div class="u-k">{{ 'sg.doc.use.purpose' | translate }}</div><div class="u-v">{{ purpose() }}</div></div>
    @if (when().length) {
      <div class="u-row"><div class="u-k">{{ 'sg.doc.use.when' | translate }}</div>
        <ul class="u-list">@for (w of when(); track w) { <li>{{ w | translate }}</li> }</ul>
      </div>
    }
    @if (behavior()) { <div class="u-row"><div class="u-k">{{ 'sg.doc.use.behavior' | translate }}</div><div class="u-v">{{ behavior() }}</div></div> }
    @if (avoid()) { <div class="u-row"><div class="u-k">{{ 'sg.doc.use.avoid' | translate }}</div><div class="u-v">{{ avoid() }}</div></div> }
  `,
  styles: [`
    :host { display: block; border: 1px solid var(--border-sub); border-radius: var(--radius-lg); overflow: hidden; }
    .u-row { display: grid; grid-template-columns: 140px 1fr; gap: 16px; padding: 12px 16px; border-bottom: 1px solid var(--border-soft); }
    .u-row:last-child { border-bottom: 0; }
    .u-k { font-size: var(--fs-13); font-weight: 600; color: var(--text-sub); }
    .u-v { font-size: var(--fs-14); color: var(--text-body); line-height: 1.55; }
    .u-list { margin: 0; padding-left: 18px; font-size: var(--fs-14); color: var(--text-body); line-height: 1.7; }
  `],
})
export class SgUse {
  readonly purpose = input('');
  readonly when = input<string[]>([]);
  readonly behavior = input('');
  readonly avoid = input('');
}

